/* The Firebrand — Act II: The Blacklist (1921–1938).
   The pit spine follows Aneurin Bevan (Nye Bowen): the blacklist, the father's death, the lockout
   and the Bedwellty guardians, the Medical Aid Society, Ebbw Vale, the Moseby memorandum and the
   New Party (a rogue fork), 1931, the means-test marches of 1935, Spain and the Unity Campaign.
   Routes: the scholar (Jennie Lee: North Lanark 1929, the ILP split), Glasgow (Shinwell: the
   Clydesiders of 1922, the Mines Department, Seaham 1935, the blow in 1938) and the objector
   (Silverman: tenants' solicitor, the city council, Nelson and Colne 1935, the refugees of 1938).
   Sources: RESEARCH.md section F; data/facts.js "The Firebrand". */
(function () {
  const TM = window.TM;
  const PIT = TM.FIRE_PIT;
  const LIVE = '~!fork-newparty31';

  Object.assign(TM.PEOPLE, {
    crisp: { name: 'Sir Stafford Crisp', role: 'A rich, ascetic barrister of the far left' },
    moseby: { name: 'Sir Oswald Moseby', role: 'A baronet in a hurry, Labour\'s rising star' },
    maxwell: { name: 'Jimmy Maxwell', role: 'Leader of the Clydesiders and the ILP' },
    cooke: { name: 'Arthur Cooke', role: 'Secretary of the Miners\' Federation' },
  });

  TM.FORKS.newparty31 = {
    title: 'The New Party',
    history: 'In March 1931 one of the coalfield\'s new Members followed Sir Oswald Moseby out of the Labour Party and into the New Party, convinced that the old men would never act on unemployment. The New Party lost every seat it fought that autumn. Within a year it had a youth movement in uniform and a leader who had been to Rome to see Mussolini. The Member from the valleys left it in disgust, but Labour would not have him back, and the valleys never forgave him.',
    more: [],
    real: 'Bevan signed the Mosley manifesto of December 1930 but refused to join the New Party, telling Mosley it would end in fascism. John Strachey and a handful of others went with Mosley and left him within months.',
    ends: { 2: { head: 'The man who went with Moseby', text: '1938. {first} {last} is {age}, out of Parliament since 1931, a lecturer for the Workers\' Educational Association in a town where nobody asks about the past. The valley sends someone else to Westminster.' } },
  };

  TM.FORKS.america23 = {
    title: 'The valley in Pennsylvania',
    history: 'In 1923 a blacklisted collier from the Sirhowy valley took a steerage passage to New York and went on to the anthracite towns of Pennsylvania, where Welsh was still spoken in the chapels. He became an organiser for the United Mine Workers, fought the coal companies\' private police through the strikes of the twenties, and was killed in 1933 in a shooting at a picket line that no court ever tried.',
    more: [],
    real: 'Bevan stayed in Tredegar through the years of unemployment, working briefly as a council labourer, and built his career on the town and its institutions.',
    ends: { 2: { head: 'Gone to America', text: 'Somewhere in Pennsylvania, {first} {last} is buried under a stone paid for by the local of the United Mine Workers. In Tredegar, a sister keeps his letters.' } },
  };

  TM.ACTS.firebrand[2] = {
    title: 'Act II · The Blacklist',
    span: '1921–1938',
    regen: 2,
    intro: 'The war boom is over. Coal prices have fallen through the floor, the owners have the mines back, and the miners have been beaten on their own. In every coalfield the lists are drawn up: the men who spoke at meetings, the men who led the lodges. Unemployment will not fall below a million for twenty years. The Labour Party is about to grow from a protest into a government. You are twenty-four.',
    continues: 'Act III of this life, from Munich to 1951, is still being written, so this life ends here for now.',
    end: (s) => s.flags.includes('mp')
      ? { head: 'The Member for {seat}', text: '1938. {first} {last} is ' + (s.year - s.born) + ', the Member for {seat}, the most dangerous back-bencher on the Labour side and the despair of the whips. Spain is lost. Austria has gone. The party leaders say rearm, but not under these men.' }
      : { head: 'Still in {town}', text: '1938. {first} {last} is ' + (s.year - s.born) + ', still in {town}, a name on every platform and on no ballot paper. The war that is coming may need people who know how to fight.' },
    start: { year: 1921 },

    scenes: [
      /* ═══════ The pit spine: blacklist to Ebbw Vale ═══════ */
      { id: 'blacklist-1922', year: 1922, title: 'The list', if: PIT,
        venue: { plate: 'city', label: 'The Labour Exchange, {town}' },
        text: 'Spring 1922. A year without work. The Tredegar Iron and Coal Company will not have you at any of its pits, and every pit for miles is theirs. The council gave you six weeks breaking stones, and the Exchange has stopped your dole because your sister earns. Your mother counts the coins on the table every Friday. A cousin in Scranton writes that the American mines are hiring Welshmen, and sends the price of a passage.',
        basis: 'Bevan\'s blacklisting by the Tredegar Iron and Coal Company after his return from the Central Labour College in 1921, and his years of unemployment, broken by six weeks as a council labourer.',
        real: 'Bevan was unemployed for nearly three years in all, and his benefit was stopped because his sister was earning. He worked for six weeks as a labourer for the council, and found work at Bedwellty colliery only in 1924; it closed ten months later. He never seriously considered leaving Tredegar, though many blacklisted miners did emigrate.',
        check: 'research', facts: ['bevan-early'],
        choices: [
          { label: 'Stay, and fight the Exchange for every shilling', effects: 'steel+2 state+2 money-2 @members+4', historical: true,
            result: 'You learn the regulations better than the clerks, and start representing other men at the Court of Referees. You win more than you lose. The Exchange begins to dread the sight of you.',
            diary: 'Won Dai Price\'s appeal. The clerk looked sick.' },
          { label: 'Take the passage to America', effects: 'money+4 fork=america23',
            result: 'You sail from Liverpool in steerage with a tin trunk and the address of a chapel in Scranton. Your mother does not come to the station.',
            diary: 'The boat. Mam would not come.' },
          { label: 'Write for the Labour papers for a few shillings', effects: 'press+3 cap+2 money+1 #wordsmith',
            result: 'The South Wales Worker pays you five shillings a column to explain why the owners are winning. You write it the way you cannot yet say it.',
            diary: 'Five bob a column. Easier to write than to say.' },
        ] },

      { id: 'father-1925', year: 1925, title: 'The dust', if: PIT,
        venue: { plate: 'bedside', label: 'Charles Street, Tredegar' },
        text: 'February 1925. Your father is dying in the front room, fighting for every breath. Forty years of coal dust in his lungs. The doctor from the Medical Aid Society comes every day and can do nothing. The company says it is not an industrial disease, so there will be no compensation; the law agrees with the company. He asks you to read to him from the Welsh hymn book. He dies in your arms on a Sunday.',
        basis: 'The death of Bevan\'s father David from pneumoconiosis in February 1925; the disease was not then compensated as an industrial disease.',
        real: 'David Bevan died in Aneurin\'s arms in February 1925 of pneumoconiosis. The family received no compensation, because the disease was not then recognised for compensation. Bevan never forgot it.',
        check: 'research', facts: ['bevan-early', 'pneumoconiosis'],
        choices: [
          { label: 'Take the compensation case to the Federation', effects: 'state+3 cap+2 #for-the-miners @members+3', historical: true,
            result: 'The Federation\'s lawyers say you will lose, and you do. But the case is on the record, and you have read every page of the Workmen\'s Compensation Act. It will be useful one day.',
            diary: 'Lost Dad\'s case. Learned the Act by heart.' },
          { label: 'Grieve, and keep it private', effects: 'health+2 @mother+5 #for-the-miners',
            result: 'You sit with your mother through the funeral and the weeks after. The valley comes to the door with food. You say nothing in public, and think a great deal.',
            diary: 'Dad buried. The chapel full.' },
          { label: 'Turn the funeral into a meeting', effects: 'press+3 temper+3 @mother-5 #for-the-miners',
            result: 'At the graveside you tell four hundred colliers what killed him and who will pay nothing for it. The minister is outraged. The colliers remember it for years.',
            diary: 'Spoke at the grave. Mam will not forgive me.' },
        ] },

      { id: 'lockout-1926-fire', year: 1926, title: 'Seven months', if: PIT + ' ' + LIVE,
        venue: { plate: 'city', label: 'The Miners\' Hall, {town}' },
        text: 'June 1926. The General Strike lasted nine days; the miners are still locked out, and will be until winter. The lodge has made you its paid disputes agent, five pounds a week, and the Council of Action runs the town: soup kitchens, boots for children, the coal tips picked over by women at dawn. The Guardians are paying relief to miners\' families, and the government says they are breaking the law.',
        basis: 'The 1926 miners\' lockout in Tredegar, where Bevan was a paid lodge official and a leader of the local Council of Action.',
        real: 'Bevan became a paid disputes agent for the lodge in 1926 and helped run the Tredegar Council of Action during the seven-month lockout, organising relief and food distribution. The miners went back on worse terms in November and December.',
        check: 'research', facts: ['bevan-early', 'lockout-1926'],
        choices: [
          { label: 'Run the relief like a government', effects: 'state+3 cap+2 order+1 @members+6', historical: true,
            result: 'You ration the soup kitchens, buy boots wholesale, and get the shopkeepers to give credit against the lodge\'s name. Nobody in Tredegar starves. You have learned how to run a town.',
            diary: 'Boots for 300 children. Nobody starved.' },
          { label: 'Lead the women to the tips, and dare the police', effects: 'steel+3 temper+2 order-2 press+2',
            roll: { stat: 'reputation', diff: 40,
              pass: { effects: 'rep+2 @members+5', result: 'The police watch and do nothing. Two hundred families have coal for the winter.', diary: 'The tips. The police watched.' },
              fail: { effects: 'rep-2 health-3 money-2', result: 'The company prosecutes for theft of coal. You get fourteen days, and the newspapers have your name.', diary: 'Fourteen days. For coal.' } } },
          { label: 'Urge the Federation to settle', effects: 'order+2 loyalty+1 @members-6',
            result: 'You say aloud what many think: the men cannot win. The lodge shouts you down, and the next meeting does not ask you to speak.',
            diary: 'Said we could not win. Shouted down.' },
        ] },

      { id: 'bedwellty-1927', year: 1927, title: 'The Guardians suspended', if: PIT + ' ' + LIVE,
        venue: { plate: 'whitehall', label: 'The Board of Guardians, Bedwellty' },
        text: 'Early 1927. The Bedwellty Guardians, miners\' men elected to run the Poor Law, paid relief to locked-out families and borrowed to do it. Now the Minister of Health, Mr Nevil Chambers, has used his new Act to remove them and send in three government commissioners. The commissioners are cutting relief to the bone. A crowd outside the workhouse wants you to tell them what to do.',
        basis: 'The Board of Guardians (Default) Act 1926, under which Neville Chamberlain as Minister of Health superseded the Bedwellty Guardians, whose union included Tredegar, in 1927.',
        real: 'In 1927 Chamberlain used the Board of Guardians (Default) Act 1926 to replace the elected Bedwellty Guardians with appointed commissioners, as he had at West Ham and Chester-le-Street, after they ran up debts paying relief to miners\' families. The episode hardened Bevan\'s lifelong contempt for Chamberlain.',
        check: 'research', facts: ['bedwellty-1927'],
        choices: [
          { label: 'Organise the relief committees outside the law', effects: 'state+3 steel+2 @members+4 order-1', historical: true,
            result: 'You set up a fund from the lodges and the shopkeepers to top up what the commissioners cut. It is not enough, but it is a rebuke. Mr Chambers becomes the man you hate most in public life.',
            diary: 'Chambers. I will remember him.' },
          { label: 'Stand for the council, and take the system over', effects: 'cap+3 order+1 fav+2',
            result: 'You decide the Poor Law will be beaten in the council chamber, not outside the workhouse. You start canvassing for the county council.',
            diary: 'County council. Take the machine.' },
          { label: 'Lead the crowd into the workhouse', effects: 'temper+3 order-3 press+3',
            roll: { stat: 'press', diff: 50,
              pass: { effects: 'rep+2', result: 'The commissioners meet a delegation and restore relief for the widows. A small win, loudly reported.', diary: 'Widows\' relief restored.' },
              fail: { effects: 'rep-2 health-2', result: 'The police clear the yard with batons. You have a split scalp and a summons.', diary: 'Batons in the workhouse yard.' } } },
        ] },

      { id: 'medical-aid-1928', year: 1928, title: 'The Medical Aid', if: PIT + ' ' + LIVE,
        venue: { plate: 'sickroom', label: 'The Cottage Hospital, {town}' },
        text: '1928. You have a seat on the county council and on the committee of the Tredegar Medical Aid Society, which charges every worker in the town a few pence a week and in return gives every family a doctor, a dentist, medicines and the cottage hospital. Walter Conroy, its secretary, wants to buy an X-ray machine. The doctors say they are overworked and want their pay raised. There is not money for both.',
        basis: 'Bevan\'s work on the Tredegar Medical Aid Society and the Cottage Hospital committee in the late 1920s, after his election to Monmouthshire County Council in 1928.',
        real: 'Bevan was elected to Monmouthshire County Council in 1928 and sat on the hospital committee of the Medical Aid Society; he chaired it in 1929–30. He later said the NHS was meant to "Tredegar-ise" Britain. The Society covered most of the town\'s population.',
        check: 'research', facts: ['bevan-early', 'medical-aid'],
        choices: [
          { label: 'Buy the X-ray machine', effects: 'state+3 cap+2 #medical-aid @conway+5', historical: true,
            result: 'The machine arrives on a lorry and half the town comes to see it. The doctors are sulky for a month. You learn that doctors can be argued with, and outlasted.',
            diary: 'X-ray machine. The doctors sulk.' },
          { label: 'Pay the doctors', effects: 'order+2 fav+2',
            result: 'The doctors are pleased and stay. The X-ray machine waits another two years. You learn what doctors want, which is not always what patients need.',
            diary: 'Paid the doctors. No X-ray yet.' },
          { label: 'Raise the subscription and do both', effects: 'state+2 money-1 @members-3',
            result: 'A penny more a week from every pay packet. The lodges grumble, then pay. The hospital gets its machine and keeps its doctors.',
            diary: 'A penny more. Both done.' },
        ] },

      { id: 'ebbw-vale-1929', year: 1929, title: 'Ebbw Vale', if: PIT + ' ' + LIVE,
        venue: { plate: 'mill', label: 'The Workmen\'s Hall, Ebbw Vale' },
        text: 'May 1929. The miners\' lodges of Ebbw Vale chose you over their sitting Member, an old Federation man, and now it is polling day. The stammer has gone, mostly; when it comes back you swerve round the word. Your meetings fill the halls of three valleys. The Liberal says you are a Bolshevik. The Conservative says nothing; he knows he has lost. You are thirty-one.',
        basis: 'Bevan\'s selection for Ebbw Vale in 1928, displacing the sitting Member Evan Davies, and his election in May 1929.',
        real: 'Bevan won Ebbw Vale in May 1929 with about 20,000 votes to 8,000, after the lodges chose him over the sitting Member in 1928. He held the seat for the rest of his life.',
        check: 'research', facts: ['bevan-early'],
        choices: [
          { label: 'Fight on the dust, the dole and the owners', effects: 'state+2 press+2 health-2', historical: true,
            roll: { stat: 'reputation', diff: 30,
              pass: { effects: 'rep+4 seat+20 !mp office=Member_for_Ebbw_Vale', result: 'Twenty thousand votes to eight. The valley carries you to the station on its shoulders. You will sit for {seat} until you die.', diary: 'Ebbw Vale! 20,000. Carried to the station.' },
              fail: { effects: 'rep+2 seat+15 !mp office=Member_for_Ebbw_Vale', result: 'A smaller majority than the old man had, and the Liberal crowing about it. But you are the Member for {seat}.', diary: 'Ebbw Vale. Smaller majority. Still in.' } } },
          { label: 'Promise the earth, specifically', effects: 'press+4 temper+2',
            roll: { stat: 'press', diff: 40,
              pass: { effects: 'rep+3 seat+15 !mp office=Member_for_Ebbw_Vale', result: 'Pithead baths, a new hospital, a steelworks. The crowds love it, and you win. They will hold you to every word.', diary: 'Won. Promised a steelworks. Gods.' },
              fail: { effects: 'rep-2', result: 'The old Member, sore at being thrown over, stands as an Independent and splits the vote. The Liberal takes the seat by ninety.', diary: 'Lost by 90. The old man split it.' } } },
          { label: 'Stay on the council: the work is here', effects: 'loyalty+2 state+2 @members+3',
            result: 'You turn the nomination down and the lodges choose another man. You will run the valley from the council chamber. Some say you were frightened of London.',
            diary: 'Stayed. The council is where the work is.' },
        ] },

      /* ═══════ The scholar's route: Fife and North Lanark ═══════ */
      { id: 'lockout-fife-1926', year: 1926, title: 'The soup kitchen in Lochgelly', if: '!route-scholar',
        venue: { plate: 'school', label: 'The Miners\' Institute, Lochgelly' },
        text: 'June 1926. You are teaching in Cowdenbeath and the miners are locked out again. Your father runs the soup kitchen; you run the children\'s concerts that pay for the soup. The ILP wants you to speak across Scotland for the miners, and offers you the fare. The education committee has warned teachers that political speaking will be noted. You have a contract to lose.',
        basis: 'Jennie Lee taught in Fife after graduating and spoke for the miners during the 1926 lockout; her family were active ILP members in Lochgelly.',
        real: 'Jennie Lee taught at a school in Cowdenbeath after university, and during the 1926 lockout spoke and raised funds for the miners. Her father ran a soup kitchen. Her speaking made her name in the ILP.',
        check: 'research', facts: ['lee-early', 'lockout-1926'],
        choices: [
          { label: 'Speak across Scotland, and let them note it', effects: 'press+4 state+2 steel+2 #orator', historical: true,
            result: 'You speak in forty towns in six weeks. The education committee notes it. The ILP notes it too, and starts looking for a seat for you.',
            diary: 'Forty towns. The ILP wants me for a seat.' },
          { label: 'Keep teaching; run the concerts', effects: 'loyalty+2 state+1 money+1 @members+3',
            result: 'You keep the contract and fill the soup pots. In the classroom, half the children fall asleep from hunger by eleven.',
            diary: 'Children asleep by eleven. Hunger.' },
          { label: 'Go to London to read law at Gray\'s Inn', effects: 'cap+3 money-2 order+1',
            result: 'You leave Fife in the middle of the lockout to read for the Bar. It is a sensible decision. Your father will not discuss it.',
            diary: 'Gray\'s Inn. Dad silent.' },
        ] },

      { id: 'north-lanark-1929', year: 1929, title: 'Before you can vote', if: '!route-scholar',
        venue: { plate: 'mill', label: 'A committee room, Bellshill' },
        text: 'March 1929. A by-election in North Lanark, a coal and steel seat held by the Tories, and the ILP has chosen you. You are twenty-four, and under the old franchise, not yet old enough to vote for yourself: the vote at twenty-one for everyone comes in only at the general election in May. The Tories say the seat needs a man of experience. You have none, except of being poor.',
        basis: 'Jennie Lee\'s victory for Labour and the ILP at the North Lanark by-election of 21 March 1929, aged 24, before the Equal Franchise Act gave women of her age the vote at the general election of May 1929.',
        real: 'Jennie Lee won North Lanark in March 1929, taking the seat from the Unionists. At twenty-four she was the youngest Member, and could not yet vote, since women under thirty were enfranchised only from the general election that May. The age here is adjusted to the character\'s birth year.',
        check: 'research', facts: ['lee-early', 'north-lanark-1929'],
        choices: [
          { label: 'Fight on poverty, and nothing else', effects: 'state+2 press+3 health-2', historical: true,
            roll: { stat: 'press', diff: 30,
              pass: { effects: 'rep+5 seat+15 !mp office=Member_for_North_Lanark', result: 'You take the seat by six thousand. The newspapers photograph you on the steps of the Commons in a borrowed hat, and you become the most famous young Member in the country.', diary: 'North Lanark! By six thousand. The youngest Member.' },
              fail: { effects: 'rep+1', result: 'You lose by a few hundred. In May, at the general election, you try again and win. It is a slower start.', diary: 'Lost by a few hundred. Won in May.' } } },
          { label: 'Fight on youth: the Tories have nothing for it', effects: 'press+4 temper+2',
            roll: { stat: 'press', diff: 45,
              pass: { effects: 'rep+4 seat+12 !mp office=Member_for_North_Lanark', result: 'The young miners and their wives turn out in thousands. You win.', diary: 'Won on the young.' },
              fail: { effects: 'rep-1', result: 'The older voters stay with the Tory. You lose, and the ILP finds someone older for May.', diary: 'Lost. Too young, they said.' } } },
          { label: 'Stand aside for a miners\' official', effects: 'loyalty+3 @members+4',
            result: 'You let the Federation have its man, and campaign for him in every village. He wins. You go back to Cowdenbeath and wait for another chance.',
            diary: 'Stood aside. He won. My turn will come.' },
        ] },

      { id: 'maiden-1929-scholar', year: 1929, title: 'The maiden speech', if: '!route-scholar !mp',
        venue: { plate: 'gallery', label: 'The House of Commons' },
        text: 'April 1929. A few weeks in the House and you have been called in the Budget debate. Across the floor sits the Chancellor of the Exchequer, Mr Winstan Churchward, sprawling, amused, writing notes. The convention is that a maiden speech is uncontroversial and the House listens politely. You have in your bag the figures for what a miner\'s family in Lanarkshire eats in a week.',
        basis: 'Jennie Lee\'s maiden speech in April 1929, an attack on Churchill\'s budget, delivered within weeks of her election.',
        real: 'Jennie Lee\'s maiden speech attacked Churchill\'s 1929 budget with a ferocity that broke the convention of uncontroversial first speeches. Churchill congratulated her afterwards. The exact wording is not used here.',
        check: 'unchecked', facts: ['lee-early', 'lee-maiden'],
        choices: [
          { label: 'Break the convention, and attack him', effects: 'press+5 temper+3 fav-2 #orator', historical: true,
            result: 'You go for him for twenty minutes: the cuts, the coal, the children. The House forgets to be polite. Afterwards Mr Churchward crosses the lobby to congratulate you, which is somehow worse.',
            diary: 'Went for Churchward. He congratulated me. Infuriating.' },
          { label: 'Keep to custom, and save it for later', effects: 'order+2 fav+3',
            result: 'You speak gently of Lanarkshire and are praised for it. Nobody remembers a word.',
            diary: 'A nice speech. Forgotten by dinner.' },
          { label: 'Read out the miner\'s weekly budget, item by item', effects: 'press+3 cap+2 state+2',
            result: 'Bread, margarine, tea, a quarter of bacon on Sundays. You read it into the record without comment. The House goes very quiet.',
            diary: 'Read out the Duncans\' budget. Silence.' },
        ] },

      { id: 'ilp-1932', year: 1932, title: 'Disaffiliation', if: '!route-scholar ' + LIVE,
        venue: { plate: 'mill', label: 'The ILP special conference' },
        text: '1932. Labour was routed in 1931 and its survivors could meet in a committee room. Now the ILP is voting to leave the Labour Party, which it helped to found, because Labour\'s whips will not let its Members vote by conscience. Jimmy Maxwell says the ILP must be a party of revolutionary socialism. Your friends in Labour say that outside the party you will be shouting into the wind for the rest of your life.',
        basis: 'The ILP\'s vote at a special conference in 1932 to disaffiliate from the Labour Party; Jennie Lee, defeated in 1931, went with the ILP.',
        real: 'The ILP disaffiliated from Labour in 1932, led by James Maxton. Jennie Lee took the ILP\'s side, against the wishes of Bevan, whom she married in 1934, and stayed with it for years, contesting North Lanark again in 1935. Most of its working-class membership drifted back to Labour within a few years.',
        check: 'research', facts: ['lee-early', 'ilp-1932'],
        choices: [
          { label: 'Go with the ILP', effects: 'state+3 loyalty-4 temper+2 !ilp', historical: true,
            result: 'You walk out with the Clydesiders. The meetings are full and the funds empty. The Labour Party calls you a splitter, and means it.',
            diary: 'Out of Labour with Maxwell. Splitters, they say.' },
          { label: 'Stay in Labour and fight from inside', effects: 'loyalty+3 fav+3 state+1',
            result: 'You stay, and join the new Socialist League, the Labour left\'s own think-tank. Some old ILP friends cut you in the street.',
            diary: 'Stayed. The Socialist League. Old friends cut me.' },
          { label: 'Leave politics for a year: lecture in America', effects: 'money+5 cap+2 press+2 #traveller',
            result: 'You sail for New York on a lecture tour: forty cities, and dollars sent home. America looks at you as a curiosity: a socialist, and young, and interesting.',
            diary: 'Forty cities. Dollars home.' },
        ] },

      /* ═══════ The Glasgow route: the Clydesiders and Seaham ═══════ */
      { id: 'st-enoch-1922', year: 1922, title: 'St Enoch\'s Station', if: '!route-glasgow',
        venue: { plate: 'city', label: 'St Enoch\'s Station, Glasgow' },
        text: 'November 1922. Labour has won most of Glasgow\'s seats, and you have taken Linlithgow. Tonight the Clydesiders leave for London, and huge crowds have come to the station to see them off with the Red Flag and the Twenty-Third Psalm. Jimmy Maxwell is on the step of the carriage. The party leaders in London are nervous of you all, and with reason.',
        basis: 'The send-off of the Clydeside Labour Members from St Enoch Station in November 1922; Shinwell won Linlithgowshire at that election.',
        real: 'In November 1922 huge crowds saw the newly elected Clydeside Members off from St Enoch Station with hymns and the Red Flag. Shinwell, elected for Linlithgowshire, was one of the group, which included Maxton, Wheatley and Kirkwood.',
        check: 'research', facts: ['shinwell-early', 'clydesiders-1922'],
        choices: [
          { label: 'Sing, and promise them everything', effects: 'press+3 state+2 seat+15 !mp office=Member_for_Linlithgow', historical: true,
            result: 'The train pulls out to the Psalm. By Carlisle the Clydesiders have agreed to abolish the slums within a Parliament. By Euston they are arguing about the order of business.',
            diary: 'St Enoch. The Psalm. Arguing by Euston.' },
          { label: 'Travel separately, as a working Member', effects: 'order+2 fav+3 seat+15 !mp office=Member_for_Linlithgow',
            result: 'You take the day train, alone, with the Mines Act and a blue pencil. The London papers note that one Clydesider seems to want office.',
            diary: 'Day train. Mines Act. One Clydesider wants office.' },
          { label: 'Make the crowd a speech about the boss class', effects: 'temper+3 press+4 seat+15 fav-3 !mp office=Member_for_Linlithgow',
            result: 'The crowd roars. The Times quotes it the next morning, with a picture. The Labour leader asks the whips who you are.',
            diary: 'The Times quoted me. MacDougal asked who I am.' },
        ] },

      { id: 'mines-1924', year: 1924, title: 'The Mines Department', if: '!route-glasgow !mp',
        venue: { plate: 'whitehall', label: 'The Mines Department, Dean Stanley Street' },
        text: 'January 1924. Labour is in office for the first time, in a minority, and Mr MacDougal has made you Secretary for Mines, outside the Cabinet. The owners want the subsidy; the miners\' secretary, Arthur Cooke, wants nationalisation. Your officials want nothing to change. You have perhaps nine months before the Liberals pull the government down. One thing could be done: a minimum wage for miners.',
        basis: 'Shinwell\'s first term as Secretary for Mines in the first Labour government, January to November 1924.',
        real: 'Shinwell was Secretary for Mines in 1924 and again in 1930–31. The first Labour government, dependent on Liberal votes, achieved little for the miners, and fell in October 1924. Shinwell lost his seat at that election and returned at a by-election in 1928.',
        check: 'research', facts: ['shinwell-early', 'shinwell-mines'],
        choices: [
          { label: 'Work the department, and settle the wages', effects: 'cap+4 order+2 fav+3 office=Secretary_for_Mines', historical: true,
            result: 'You master the figures in a month and broker a wage agreement better than the owners wanted. The miners say it is not enough. The government falls in October, and you lose your seat with it.',
            diary: 'Wage agreement. Not enough. Out in October.' },
          { label: 'Bring in a nationalisation bill, and let it fail', effects: 'state+4 press+3 fav-4 office=Secretary_for_Mines',
            result: 'The bill is talked out by Liberals and Tories together. The miners cheer you. The Prime Minister does not speak to you for a month.',
            diary: 'Bill talked out. Miners cheered. MacDougal silent.' },
          { label: 'Refuse office under MacDougal', effects: 'state+2 temper+2 fav-6 @maxwell+5',
            result: 'You tell the Prime Minister you will not serve a government that dare not act. Maxwell says it is the best thing you have done. The whips write your name in a book.',
            diary: 'Refused office. Maxwell pleased. The whips\' book.' },
        ] },

      { id: 'seaham-1935', year: 1935, title: 'Seaham', if: '!route-glasgow ' + LIVE,
        venue: { plate: 'mill', label: 'The Miners\' Hall, Seaham Harbour' },
        text: 'November 1935. You lost Linlithgow in the 1931 rout. Now the Durham miners have asked you to stand at Seaham against Mr MacDougal himself, the former Labour leader, who left them to head a Tory government and now sits there as the National Labour Member. It will be the most watched fight of the election. He is old and ill. You will be called cruel whatever you do.',
        basis: 'Shinwell\'s defeat of Ramsay MacDonald at Seaham in the general election of November 1935.',
        real: 'Shinwell beat MacDonald at Seaham in November 1935 by over 20,000 votes, the most celebrated result of the election. MacDonald returned to the Commons at a by-election and died in 1937.',
        check: 'research', facts: ['shinwell-early', 'seaham-1935'],
        choices: [
          { label: 'Fight him on the means test and 1931', effects: 'steel+3 temper+2 press+4', historical: true,
            roll: { stat: 'reputation', diff: 40,
              pass: { effects: 'rep+6 seat+25 !mp set:seat=Seaham office=Member_for_Seaham', result: 'Twenty thousand votes ahead. The old man\'s face at the count. You do not gloat, quite. The Durham miners carry you through the streets.', diary: 'Seaham. Beat MacDougal by 20,000. His face.' },
              fail: { effects: 'rep+1 seat+10 !mp set:seat=Seaham office=Member_for_Seaham', result: 'A narrower margin than you hoped; sympathy for the old man ran deeper than expected. But you win.', diary: 'Seaham, narrowly. They pitied him.' } } },
          { label: 'Fight a clean campaign: no personal attacks', effects: 'order+2 fav+3',
            roll: { stat: 'favour', diff: 40,
              pass: { effects: 'rep+4 seat+20 !mp set:seat=Seaham office=Member_for_Seaham', result: 'You win on policy, and the papers praise your restraint.', diary: 'Seaham, cleanly.' },
              fail: { effects: 'rep-1 -!mp office=None', result: 'The miners wanted blood, and some stay at home. MacDougal holds on by a few hundred.', diary: 'Lost Seaham. Too gentle.' } } },
          { label: 'Refuse: let a Durham man have it', effects: 'loyalty+2 @members+3 -!mp office=None',
            result: 'A local checkweighman takes the nomination and beats MacDougal handsomely. You are still without a seat.',
            diary: 'Let the Durham man have it. He won.' },
        ] },

      { id: 'bower-1938', year: 1938, title: 'Go back to Poland', if: '!route-glasgow !mp',
        venue: { plate: 'gallery', label: 'The House of Commons' },
        text: 'April 1938. A debate on Spain, and you are hammering the government. A Tory back-bencher, Commander Bowyer, shouts across the floor that you should go back to Poland. You were born in Spitalfields. Your father came from Poland with nothing. The House has gone silent, waiting to see what you will do. You are across the gangway from him in four steps.',
        basis: 'The incident of 4 April 1938, in a debate on Spain, in which Shinwell crossed the floor and struck the Conservative Member Robert Bower after Bower told him to go back to Poland.',
        real: 'In April 1938 Commander Robert Bower interrupted Shinwell with a remark telling him to go back to Poland. Shinwell crossed the floor and hit him. The blow burst Bower\'s eardrum. Both men later apologised to the House.',
        check: 'research', facts: ['shinwell-bower'],
        choices: [
          { label: 'Cross the floor and hit him', effects: 'temper+4 steel+2 press+4 fav-4 #hothead', historical: true,
            result: 'You cross the floor and strike him across the face. Uproar. The Speaker suspends the sitting. You apologise to the House the next day, and to nobody else.',
            diary: 'Hit Bowyer. Apologised to the House, not him.' },
          { label: 'Turn to the Speaker and demand withdrawal', effects: 'order+2 fav+3 press+2',
            result: 'The Speaker makes him withdraw. He does so, ungraciously. You finish your speech to cheers from both sides.',
            diary: 'Bowyer withdrew. Finished to cheers.' },
          { label: 'Answer him with a speech on the refugees', effects: 'cap+3 press+3 state+1',
            result: 'You tell the House what is happening to Jews in Vienna this week, and ask whether the Member would like to send them back too. He walks out.',
            diary: 'Vienna. He walked out.' },
        ] },

      /* ═══════ The objector's route: Liverpool and Nelson ═══════ */
      { id: 'tenants-1927', year: 1927, title: 'The tenants\' solicitor', if: '!route-co',
        venue: { plate: 'city', label: 'An office in Dale Street, Liverpool' },
        text: '1927. Your brass plate is up at last: a solicitor, with a criminal record from the war that the Law Society chose to overlook. Your clients cannot pay. A widow whose landlord wants her out of a court off Scotland Road; a docker with a crushed foot and an employer who says he was drunk; a family facing eviction for arrears run up during the lockout. A shipping firm offers you its debt-collecting at three times the money.',
        basis: 'Sydney Silverman\'s practice as a Liverpool solicitor from the late 1920s, acting for tenants and injured workmen.',
        real: 'Silverman qualified as a solicitor and practised in Liverpool, building a reputation for representing tenants and workers in compensation cases. It made his name in the city\'s labour movement.',
        check: 'research', facts: ['silverman-early'],
        choices: [
          { label: 'Take the widow, the docker and the family', effects: 'state+3 cap+2 money-3 @members+5', historical: true,
            result: 'You win the docker\'s case and keep the widow in her house for another year. The family goes. You learn the Rent Acts better than any landlord\'s solicitor in Liverpool.',
            diary: 'Docker\'s compensation won. The family evicted.' },
          { label: 'Take the shipping firm, and the tenants for free', effects: 'money+5 health-3 cap+2',
            result: 'You work eighteen hours a day, collecting debts for the shipowners by morning and fighting landlords by night. It pays, and it is wearing you down.',
            diary: 'Eighteen hours. Debts by day, tenants by night.' },
          { label: 'Organise the tenants into an association', effects: 'state+3 press+3 order-1',
            result: 'A Tenants\' Defence Association, two thousand members, with you as its honorary solicitor. The landlords start to settle rather than face you.',
            diary: 'Tenants\' Defence. 2,000. The landlords settle.' },
        ] },

      { id: 'nelson-1935', year: 1935, title: 'Nelson and Colne', if: '!route-co ' + LIVE,
        venue: { plate: 'mill', label: 'The Weavers\' Institute, Nelson' },
        text: 'November 1935. You have sat on Liverpool City Council for three years. Now Nelson and Colne, the reddest weaving towns in Lancashire, have chosen you to win back the seat lost in 1931. Little Moscow, the papers call Nelson. The mills are on short time and the weavers fighting the more-looms system. You are a Liverpool Jewish lawyer with a pacifist past, in a town of Methodist weavers.',
        basis: 'Silverman\'s election for Nelson and Colne in November 1935, after sitting on Liverpool City Council from 1932.',
        real: 'Silverman sat on Liverpool City Council from 1932 to 1938 and won Nelson and Colne in 1935, holding it until his death in 1968. Nelson was famous as a radical town, known as "Little Moscow".',
        check: 'research', facts: ['silverman-early', 'silverman-nelson'],
        choices: [
          { label: 'Fight on the looms and the means test', effects: 'state+2 press+2 @members+4', historical: true,
            roll: { stat: 'reputation', diff: 35,
              pass: { effects: 'rep+4 seat+20 !mp office=Member_for_Nelson_and_Colne', result: 'You win back the seat comfortably. The weavers find that the lawyer knows the Factory Acts better than their own officials.', diary: 'Nelson and Colne! The weavers\' lawyer.' },
              fail: { effects: 'rep+1 seat+12 !mp office=Member_for_Nelson_and_Colne', result: 'A narrow win, with the chapel vote split. But you are in.', diary: 'Nelson, narrowly.' } } },
          { label: 'Fight on peace and the League', effects: 'state+1 press+3 empire-2',
            roll: { stat: 'press', diff: 45,
              pass: { effects: 'rep+3 seat+15 !mp office=Member_for_Nelson_and_Colne', result: 'Nelson is a pacifist town, and it votes for you.', diary: 'Peace won Nelson.' },
              fail: { effects: 'rep-1', result: 'Abyssinia has made peace sound like weakness. The National candidate holds the seat.', diary: 'Lost. Abyssinia.' } } },
          { label: 'Stay on the council in Liverpool', effects: 'loyalty+2 cap+2',
            result: 'You turn Nelson down. Liverpool\'s slums are bad enough to fill a lifetime.',
            diary: 'Stayed in Liverpool. The slums.' },
        ] },

      { id: 'refugees-1938', year: 1938, title: 'November 1938', if: '!route-co ' + LIVE,
        venue: { plate: 'whitehall', label: 'The Home Office, Whitehall' },
        text: 'November 1938. The synagogues of Germany have burned in a single night, and thirty thousand Jewish men have been taken to the camps. The Home Office is admitting refugees only if someone guarantees they will not cost the public a penny. You have letters on your desk from families in Vienna and Berlin with your surname. You were jailed three times for refusing to fight. You are not sure you would refuse now.',
        basis: 'Kristallnacht, 9–10 November 1938, and the British refugee policy of guarantees; Silverman abandoned his pacifism over the Nazi persecution of the Jews and worked for refugees.',
        real: 'After Kristallnacht Britain admitted about 10,000 unaccompanied children on the Kindertransport and some thousands of adults, mostly on private guarantees. Silverman, a former absolutist objector, gave up his pacifism as the persecution of the Jews grew, and later chaired the British section of the World Jewish Congress.',
        check: 'research', facts: ['silverman-early', 'kristallnacht-1938'],
        choices: [
          { label: 'Guarantee every family you can, and ask the Home Office for more', effects: 'state+2 money-6 empire-1 #refugees', historical: true,
            result: 'You sign guarantees until your bank manager telephones. Eleven people reach Liverpool before the war. You lie awake over the ones who do not.',
            diary: 'Eleven guaranteed. The rest. I cannot think of the rest.' },
          { label: 'Say publicly that you were wrong about war', effects: 'steel+4 press+3 empire+2',
            result: 'You tell a Nelson meeting that some things must be fought. Your old pacifist friends write you sad letters. The Tories are surprised.',
            diary: 'Told Nelson I was wrong. Sad letters.' },
          { label: 'Press the Home Secretary to drop the guarantees', effects: 'state+3 fav-3 cap+2',
            result: 'The Home Secretary is courteous and immovable. The guarantees stay. You put your questions on the Order Paper every week until war comes.',
            diary: 'The guarantees stay. Questions every week.' },
        ] },

      /* ═══════ The Member for {seat}: shared hinges ═══════ */
      { id: 'moseby-1930', year: 1930, title: 'The memorandum', if: '!mp ~!route-glasgow ~!route-co',
        venue: { plate: 'club', label: 'A house in Smith Square' },
        text: 'December 1930. Unemployment is past two and a half million and the government does nothing. Sir Oswald Moseby has resigned from it over his plan for public works and protection, and now he wants Labour Members to sign his manifesto; even Arthur Cooke of the miners has signed. He is rich, brilliant and impatient. Over dinner he hints that if the party will not move, a new party might. He looks at you as if you were already in it.',
        basis: 'The Mosley Memorandum of 1930 and the Mosley Manifesto of December 1930, signed on 6 December 1930 by Mosley, his wife Cynthia and fifteen other Labour MPs, among them Bevan and Strachey, with A. J. Cook of the miners; Mosley founded the New Party in early 1931.',
        real: 'Bevan signed the Mosley manifesto in December 1930 but refused to join the New Party in 1931, warning that it would end in fascism. John Strachey went with Mosley, and left him within months.',
        check: 'research', facts: ['mosley-memo', 'bevan-early'],
        choices: [
          { label: 'Sign the manifesto, but stay in Labour', effects: 'state+3 cap+2 fav-3 @moseby+5', historical: true,
            result: 'You sign. In March, when Moseby founds his New Party, you tell him to his face that it will end with a uniform and a balcony. He laughs. You do not.',
            diary: 'Signed. Told Moseby: it ends in uniform. He laughed.' },
          { label: 'Sign, and follow him out', effects: 'state+2 order+3 loyalty-6 fork=newparty31',
            result: 'In March 1931 you walk out of the Labour Party with Moseby. The valley reads about it in the Western Mail.',
            diary: 'Out with Moseby. God help me.' },
          { label: 'Refuse to sign: the man is dangerous', effects: 'loyalty+3 fav+3 order-1 @moseby-5',
            result: 'You tell him the policy is good and the man is not. He shrugs. The whips note your loyalty with surprise.',
            diary: 'Did not sign. The whips surprised.' },
        ] },

      { id: 'election-1931-fire', year: 1931, title: 'The landslide', if: '!mp ' + LIVE + ' ~!route-glasgow ~!route-co',
        venue: { plate: 'mill', label: 'The count, {seat}' },
        text: 'October 1931. Mr MacDougal has gone over to lead a National Government with the Tories, and called an election to crush his old party. Labour is being wiped out in seat after seat: the Post Office Savings, the papers say, are not safe with Labour. In {seat} the miners are steadier than most. You can hold on if you spend every hour of the campaign at home.',
        basis: 'The general election of October 1931, in which Labour fell to 52 seats; Bevan held Ebbw Vale, while Jennie Lee lost North Lanark.',
        real: 'In 1931 Labour was reduced to 52 seats. Bevan was one of the few Labour Members returned unopposed, at Ebbw Vale. Jennie Lee lost North Lanark. The National Government won 554 seats.',
        check: 'research', facts: ['election-1931'],
        choices: [
          { label: 'Stay in the constituency every day', effects: 'seat+5 loyalty+1 health-1', historical: true,
            roll: { stat: 'seat', diff: -15,
              pass: { effects: 'rep+2', result: 'You hold {seat}, one of fifty-two Labour Members left. The parliamentary party could meet in a committee room.', diary: 'Held {seat}. One of 52.' },
              fail: { effects: '-!mp rep-3 office=None', result: 'You lose by a few hundred. The landslide has reached even here.', diary: 'Lost {seat}. The landslide.' } } },
          { label: 'Tour the country for colleagues in danger', effects: 'press+3 fav+3 seat-5',
            roll: { stat: 'seat', diff: 35,
              pass: { effects: 'rep+3', result: 'Your colleagues mostly lose, but you hold your own seat. The party remembers that you came.', diary: 'Toured. Held on. They remember.' },
              fail: { effects: '-!mp rep-2 office=None', result: 'You lose your own seat while defending other people\'s.', diary: 'Lost mine helping others.' } } },
          { label: 'Denounce MacDougal as a traitor, everywhere', effects: 'press+4 temper+3 seat+2',
            roll: { stat: 'seat', diff: 25,
              pass: { effects: 'rep+2', result: 'The miners like it, and you hold.', diary: 'Traitor, I said. Held.' },
              fail: { effects: '-!mp rep-2 office=None', result: 'The swing is too strong. You lose.', diary: 'Lost.' } } },
        ] },

      { id: 'means-test-1935-fire', year: 1935, title: 'The new scales', if: LIVE + ' ~!route-co',
        venue: { plate: 'city', label: 'The road from {town}' },
        text: 'February 1935. The new Unemployment Assistance Board has published its scales, and in the valleys they mean a cut for most families on the dole, with the household means test pursuing every sixpence a son or daughter earns. The coalfields are marching: whole towns on the roads, chapels and lodges and shopkeepers together, hundreds of thousands across South Wales in a single week. The government is shaken.',
        basis: 'The protests of January–February 1935 against the new scales of the Unemployment Assistance Board under the Unemployment Act 1934, which forced the government to suspend them (the "standstill").',
        real: 'The UAB\'s new scales took effect on 7 January 1935 and cut benefit for many. Mass demonstrations followed, largest in South Wales, where hundreds of thousands are said to have marched in early February; at Merthyr on 4 February women stormed the UAB office. The government retreated within weeks, passing a standstill order that let claimants keep the higher of the old and new rates.',
        check: 'unchecked', facts: ['uab-1935'],
        choices: [
          { label: 'March at the head of your people', effects: 'state+3 press+4 @members+6 health-2', historical: true,
            result: 'Ten miles in the February rain with sixty thousand people. Two weeks later the government suspends the scales. It is the first victory over the means test, and it was won in the street.',
            diary: 'Ten miles in the rain. The standstill! Won in the street.' },
          { label: 'Fight it clause by clause in the House', effects: 'cap+3 order+1 fav+2',
            result: 'You table amendments and harry the minister at every Question Time. When the standstill comes, the minister gives the marchers the credit, not you.',
            diary: 'Harried the minister. The marchers got the credit.' },
          { label: 'Join the Communists\' march, and share the platform', effects: 'state+3 temper+2 loyalty-3 fav-4',
            result: 'You speak alongside the Communist organisers. The crowd does not care whose banner it is. Transport House does, and starts a file.',
            diary: 'Shared a platform with the Party. Transport House has a file.' },
        ] },

      { id: 'cable-street-1936', year: 1936, title: 'Cable Street', if: '!route-glasgow|!route-co ' + LIVE,
        venue: { plate: 'city', label: 'Gardiner\'s Corner, Whitechapel' },
        text: 'Sunday, 4 October 1936. Sir Oswald Moseby means to march his Blackshirts through the Jewish East End, and the police will clear the road for him. Labour and the Board of Deputies have told people to stay at home. Instead a hundred thousand East Enders are in the streets: dockers, tailors, Irish and Jewish. There is a barricade going up in Cable Street, and a lorry turned over.',
        basis: 'The Battle of Cable Street, 4 October 1936, when crowds blocked a march by Mosley\'s British Union of Fascists; Labour and Jewish community leaders had urged people to stay away.',
        real: 'On 4 October 1936 a huge crowd, estimated at 100,000 or more, blocked the BUF march at Gardiner\'s Corner and in Cable Street. The police told Mosley the march could not go ahead through the East End, and his column was turned west. The Public Order Act 1936 followed, banning political uniforms.',
        check: 'research', facts: ['cable-street-1936'],
        choices: [
          { label: 'Go to the barricade', effects: 'steel+3 state+2 press+2 health-2', historical: true,
            roll: { stat: 'health', diff: 25,
              pass: { effects: 'rep+2', result: 'By the afternoon the police commissioner tells Moseby he cannot go through. The Blackshirts march away west, to the Embankment. The East End sings.', diary: 'They did not pass.' },
              fail: { effects: 'health-4', result: 'A mounted policeman\'s baton opens your scalp. You see the Blackshirts turn back from a stretcher.', diary: 'Baton. They turned back.' } } },
          { label: 'Do as the party asks, and hold a meeting elsewhere', effects: 'loyalty+3 fav+2',
            result: 'You address a peace rally in Hyde Park to a few hundred people. The East End does not forget who was where.',
            diary: 'Hyde Park. Few hundred. The East End noticed.' },
          { label: 'Watch from a window, and write it up', effects: 'press+3 cap+2',
            result: 'Your account, in the New Statesman, is the best written that week. You were not at the barricade.',
            diary: 'Wrote it up. Not at the barricade.' },
        ] },

      { id: 'spain-1936-fire', year: 1936, title: 'Non-intervention', if: LIVE,
        venue: { plate: 'gallery', label: 'The Labour conference, Edinburgh' },
        text: 'October 1936. Franco\'s generals have risen against the Spanish Republic, with German and Italian planes behind them. Britain and France have proposed non-intervention: no arms to either side. The Labour leaders have backed it, for fear of a war, and of the French government falling. The Spanish delegates have just spoken to the conference, and the hall is weeping. Young men from {town} are leaving for Spain.',
        basis: 'The Labour conference at Edinburgh in October 1936, which supported non-intervention after hearing Spanish Republican delegates; Bevan and the left opposed it.',
        real: 'Labour\'s 1936 conference backed non-intervention, but the party reversed its position within weeks as German and Italian intervention became plain. Bevan was a fierce critic of non-intervention. More than 2,300 volunteers from Britain, Ireland and the Commonwealth served in the International Brigades, and over 500 were killed, many of them South Wales miners.',
        check: 'research', facts: ['spain-1936', 'international-brigades'],
        choices: [
          { label: 'Speak against non-intervention', effects: 'state+2 press+4 fav-3 temper+2', historical: true,
            result: 'You tell the conference that non-intervention is intervention for Franco. You lose the vote. Within weeks the leaders quietly change their minds, and never thank you.',
            diary: 'Non-intervention is intervention for Franco. Lost. Right.' },
          { label: 'Go to Spain yourself', effects: 'steel+5 state+2 health-4 #spain',
            death: { chance: 0.18, text: 'You are killed at the Jarama in February 1937, in a machine-gun barrage on Suicide Hill, with the British Battalion. You are buried in an olive grove with the others.', headline: 'Killed at the Jarama' },
            result: 'You cross the Pyrenees on foot and spend a winter with the British Battalion. You come home thinner, with a wound in the arm and the names of the men from {town} who will not.',
            diary: 'Home from Spain. The names.' },
          { label: 'Raise money and food ships for Spain', effects: 'state+2 cap+2 money-2 @members+4',
            result: 'Every lodge, every chapel, every co-operative: a food ship from Swansea in March. It is small. It is something.',
            diary: 'A food ship from Swansea.' },
        ] },

      { id: 'unity-1937', year: 1937, title: 'The Unity Campaign', if: LIVE + ' ~!fork-america23',
        venue: { plate: 'ballroom', label: 'The Free Trade Hall, Manchester' },
        text: 'January 1937. Sir Stafford Crisp, a millionaire barrister who lives on nuts and vegetables, has launched a campaign for a united front of Labour, the ILP and the Communists against fascism, and a new weekly paper, Tribune, with his money. He wants you on his platforms. The Labour executive has warned that anyone who shares a platform with Communists will be expelled. The hall tonight holds four thousand.',
        basis: 'The Unity Campaign launched in January 1937 by Cripps\'s Socialist League with the ILP and the Communist Party; Tribune was founded the same month; the Labour NEC disaffiliated the League and threatened its members.',
        real: 'The Unity Campaign was launched in Manchester in January 1937. The Labour NEC disaffiliated the Socialist League and declared its members ineligible for Labour membership; the League dissolved itself in May 1937. Bevan was on Tribune\'s board from the start. Expulsions followed in 1939.',
        check: 'research', facts: ['unity-1937', 'tribune-1937'],
        choices: [
          { label: 'Share the platform, and write for Tribune', effects: 'state+3 press+4 loyalty-3 fav-4 @crisp+8 !tribune', historical: true,
            result: 'You speak with Crisp and a Communist and the ILP\'s leader on one platform. The cheering lasts ten minutes. The executive starts drawing up its list.',
            diary: 'Crisp\'s platform. Ten minutes\' cheering. The list.' },
          { label: 'Write for Tribune, but refuse the platform', effects: 'press+3 cap+2 @crisp+3 !tribune',
            result: 'You give Crisp your pen but not your presence. The executive cannot quite expel you for an article. Not yet.',
            diary: 'Tribune, yes. The platform, no.' },
          { label: 'Stay clear: the party is the only instrument', effects: 'loyalty+4 fav+4 @crisp-4',
            result: 'You tell Crisp the Communists will use him and drop him. He thinks you have lost your nerve. The whips think you have found your sense.',
            diary: 'Told Crisp no. Lost nerve, he thinks.' },
        ] },

      /* ═══════ Out of the House ═══════ */
      { id: 'out-1937-fire', year: 1937, title: 'A meeting in the rain', if: '~!mp ' + LIVE + ' ~!fork-america23',
        venue: { plate: 'city', label: 'The square, {town}' },
        text: 'September 1937. Still no seat. You make your living from articles, lectures and the lodge, and you speak somewhere every night: a street corner, a chapel vestry, a co-operative hall. Tonight it is raining, forty people under umbrellas, and a man at the back asks why he should listen to someone the Labour Party will not even nominate. It is a fair question. You have five minutes before the bus.',
        basis: 'A composite of the inter-war Labour left outside Parliament: Jennie Lee after 1931, Shinwell between 1931 and 1935, and many local militants.',
        real: 'Jennie Lee spent the years after 1931 outside Parliament as an ILP speaker, writer and lecturer, failing to win a seat until 1945. Shinwell spent 1931–35 out of the House. This scene is a composite.',
        check: 'research', facts: ['lee-early', 'shinwell-early'],
        choices: [
          { label: 'Tell him the truth: the party is wrong, and you will say so', effects: 'press+2 temper+2 @members+3', historical: true,
            result: 'The forty stay in the rain to the end. You miss the bus and walk six miles home, happy.',
            diary: 'Forty in the rain. Walked home happy.' },
          { label: 'Make peace with the party, and ask for a seat', effects: 'loyalty+3 fav+4 state-1',
            result: 'You write a careful letter to Transport House. A seat is mentioned for the next election, a hard one.',
            diary: 'A careful letter. A hard seat offered.' },
          { label: 'Give it up for a while, and earn a living', effects: 'money+5 health+3 press-2',
            result: 'You take a year\'s work as a newspaper\'s labour correspondent. It pays, and you sleep. The meetings go on without you.',
            diary: 'A labour correspondent. Sleep.' },
        ] },
    ],
  };
})();
